ALTER TABLE audit_events ADD COLUMN details_json TEXT;
CREATE INDEX audit_retention ON audit_events(created_at);
CREATE TRIGGER issue_state_audit AFTER UPDATE OF state ON issues WHEN OLD.state!=NEW.state BEGIN INSERT INTO audit_events(id,group_id,action,target,created_at,details_json) VALUES(lower(hex(randomblob(16))),NEW.group_id,'issue.state_changed',NEW.id,unixepoch('subsec')*1000,json_object('from',OLD.state,'to',NEW.state)); END;
CREATE TRIGGER mail_state_audit AFTER UPDATE OF state ON email_outbox WHEN OLD.state!=NEW.state BEGIN INSERT INTO audit_events(id,group_id,action,target,created_at,details_json) VALUES(lower(hex(randomblob(16))),NEW.group_id,'mail.state_changed',NEW.id,unixepoch('subsec')*1000,json_object('from',OLD.state,'to',NEW.state,'error_code',CASE WHEN NEW.error_code IS NULL THEN NULL WHEN NEW.error_code IN ('E_RECIPIENT_SUPPRESSED','E_RECIPIENT_NOT_VERIFIED','E_CONFIGURATION','E_RATE_LIMITED','E_DAILY_LIMIT_EXCEEDED','UNKNOWN_SEND_RESULT','lease_expired','expired','delivery_window_expired','ineligible_recipient','membership_or_preference','issue_or_submission_changed','mail_not_configured','publication_missing','message_preparation_failed','issue_changed','group_deleted','superseded') THEN NEW.error_code ELSE 'redacted_error' END)); END;
CREATE TRIGGER export_state_audit AFTER UPDATE OF state ON exports WHEN OLD.state!=NEW.state BEGIN INSERT INTO audit_events(id,group_id,action,target,created_at,details_json) VALUES(lower(hex(randomblob(16))),NEW.group_id,'export.state_changed',NEW.id,unixepoch('subsec')*1000,json_object('from',OLD.state,'to',NEW.state)); END;
